## Introduction

Redis est une base de données en mémoire ultra-rapide. Idéal pour le cache, les sessions, les files d'attente et la messagerie temps réel.

## Connexion et opérations de base

```javascript
import { createClient } from 'redis';

const redis = createClient({ url: process.env.REDIS_URL });
await redis.connect();

// Strings
await redis.set('user:1:name', 'Alice', { EX: 3600 }); // Expire en 1h
const name = await redis.get('user:1:name');

// Hash
await redis.hSet('user:1', { name: 'Alice', email: 'alice@ex.com' });
const user = await redis.hGetAll('user:1');

// Liste
await redis.lPush('notifications', JSON.stringify({ type: 'like', userId: 42 }));
const notif = await redis.rPop('notifications');

// Set
await redis.sAdd('online-users', '1', '2', '3');
const isOnline = await redis.sIsMember('online-users', '1');
```

## Cache API avec TTL

```javascript
async function getCachedData(key, fetchFn, ttl = 300) {
  // Essayer le cache d'abord
  const cached = await redis.get(key);
  if (cached) return JSON.parse(cached);

  // Calculer et stocker
  const data = await fetchFn();
  await redis.set(key, JSON.stringify(data), { EX: ttl });
  return data;
}

// Usage
const users = await getCachedData(
  'all-users',
  () => db.user.findMany(),
  600  // 10 minutes
);
```

## Pub/Sub pour le temps réel

```javascript
// Publisher
async function publishEvent(channel, data) {
  await redis.publish(channel, JSON.stringify(data));
}

// Subscriber (client séparé !)
const subscriber = redis.duplicate();
await subscriber.connect();

await subscriber.subscribe('user-events', (message) => {
  const event = JSON.parse(message);
  console.log('Événement reçu:', event);
  // Notifier via WebSocket, etc.
});

// Publier depuis une autre partie du code
await publishEvent('user-events', { type: 'login', userId: 123 });
```

## Rate limiting

```javascript
async function rateLimit(userId, limit = 100, window = 60) {
  const key = `rate:${userId}:${Math.floor(Date.now() / (window * 1000))}`;
  const count = await redis.incr(key);
  if (count === 1) await redis.expire(key, window);
  return count <= limit;
}

// Dans un middleware
if (!await rateLimit(req.userId)) {
  return res.status(429).json({ error: 'Too many requests' });
}
```

## Conclusion

Redis est essentiel en production. Upstash propose Redis serverless avec une offre gratuite généreuse.

## Introduction

Prisma est l'ORM TypeScript moderne. Son client généré garantit des requêtes type-safe et son studio visuel te permet d'explorer tes données.

## Installation

```bash
npm install prisma @prisma/client
npx prisma init
```

## Schéma Prisma

```prisma
// prisma/schema.prisma
generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

model User {
  id        Int      @id @default(autoincrement())
  email     String   @unique
  name      String
  role      Role     @default(USER)
  posts     Post[]
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
}

model Post {
  id        Int      @id @default(autoincrement())
  title     String
  content   String?
  published Boolean  @default(false)
  author    User     @relation(fields: [authorId], references: [id])
  authorId  Int
  tags      Tag[]
}

model Tag {
  id    Int    @id @default(autoincrement())
  name  String @unique
  posts Post[]
}

enum Role {
  USER
  ADMIN
  MODERATOR
}
```

## Migrations

```bash
# Créer et appliquer une migration
npx prisma migrate dev --name add-user-table

# Appliquer en production
npx prisma migrate deploy

# Explorer les données
npx prisma studio
```

## Requêtes CRUD

```typescript
import { PrismaClient } from '@prisma/client';

const prisma = new PrismaClient();

// CREATE
const user = await prisma.user.create({
  data: { email: 'alice@ex.com', name: 'Alice' }
});

// READ avec relations
const userWithPosts = await prisma.user.findUnique({
  where: { email: 'alice@ex.com' },
  include: { posts: { where: { published: true } } }
});

// UPDATE
await prisma.user.update({
  where: { id: 1 },
  data: { role: 'ADMIN' }
});

// DELETE
await prisma.user.delete({ where: { id: 1 } });

// Recherche + pagination
const posts = await prisma.post.findMany({
  where: {
    published: true,
    author: { role: 'ADMIN' },
    title: { contains: 'TypeScript', mode: 'insensitive' }
  },
  orderBy: { createdAt: 'desc' },
  take: 10,
  skip: 20,
  include: { author: true, tags: true }
});
```

## Conclusion

Prisma élimine les erreurs de typo dans les requêtes SQL. Son générateur de types rend les refactors beaucoup plus sûrs.

## Introduction

tRPC permet d'appeler tes fonctions backend depuis le frontend avec une autocomplétion parfaite. Zéro génération de code, zéro schema.

## Installation

```bash
npm install @trpc/server @trpc/client @trpc/react-query @tanstack/react-query zod
```

## Serveur tRPC

```typescript
// server/trpc.ts
import { initTRPC } from '@trpc/server';
import { z } from 'zod';

const t = initTRPC.create();

export const router = t.router;
export const publicProcedure = t.procedure;
export const middleware = t.middleware;

// server/routers/user.ts
const userRouter = router({
  list: publicProcedure.query(async () => {
    return await db.user.findMany();
  }),

  byId: publicProcedure
    .input(z.object({ id: z.number() }))
    .query(async ({ input }) => {
      return await db.user.findUnique({ where: { id: input.id } });
    }),

  create: publicProcedure
    .input(z.object({
      name: z.string().min(2),
      email: z.string().email()
    }))
    .mutation(async ({ input }) => {
      return await db.user.create({ data: input });
    }),
});

// server/root.ts
export const appRouter = router({ user: userRouter });
export type AppRouter = typeof appRouter;
```

## Intégration Next.js

```typescript
// app/api/trpc/[trpc]/route.ts
import { fetchRequestHandler } from '@trpc/server/adapters/fetch';
import { appRouter } from '@/server/root';

const handler = (req: Request) =>
  fetchRequestHandler({
    endpoint: '/api/trpc',
    req,
    router: appRouter,
    createContext: () => ({}),
  });

export { handler as GET, handler as POST };
```

## Client React

```tsx
// utils/trpc.ts
import { createTRPCReact } from '@trpc/react-query';
import type { AppRouter } from '@/server/root';

export const trpc = createTRPCReact<AppRouter>();

// Composant
function UserList() {
  const { data: users, isLoading } = trpc.user.list.useQuery();
  const createUser = trpc.user.create.useMutation({
    onSuccess: () => utils.user.list.invalidate()
  });

  return (
    <div>
      {users?.map(u => <div key={u.id}>{u.name}</div>)}
      <button onClick={() => createUser.mutate({ name: 'Bob', email: 'bob@ex.com' })}>
        Créer
      </button>
    </div>
  );
}
```

## Conclusion

tRPC élimine tout désalignement entre front et back. Si tu renommes une procédure côté serveur, TypeScript te signale immédiatement toutes les utilisations frontend.
